# filename: ledger_service/app/services/balance_service.py

import logging
from decimal import Decimal

from sqlalchemy import func
from sqlalchemy.orm import Session

from ledger_service.app.config import settings
from ledger_service.app.models.ledger import Account, LedgerEntry
from ledger_service.app.schemas.ledger import BalanceSummary, PlatformSummary
from ledger_service.app.services.account_service import get_merchant_account_id

logger = logging.getLogger(__name__)


def get_merchant_balance(
    db: Session, merchant_id: str, currency: str = "usd"
) -> BalanceSummary:
    """Get full balance summary for a merchant"""
    account_id = get_merchant_account_id(merchant_id, currency)
    account = db.query(Account).filter(Account.id == account_id).first()

    if not account:
        return BalanceSummary(
            merchant_id=merchant_id,
            currency=currency,
            available_balance=Decimal(0),
            pending_balance=Decimal(0),
            total_balance=Decimal(0),
            total_earned=Decimal(0),
            total_fees_paid=Decimal(0),
            total_refunded=Decimal(0),
        )

    # Total earned (all captured payments net)
    total_earned = db.query(func.sum(LedgerEntry.amount)).filter(
        LedgerEntry.account_id == account_id,
        LedgerEntry.entry_type == "debit",
        LedgerEntry.event_type == "payment.captured",
    ).scalar() or Decimal(0)

    # Total refunded
    total_refunded = db.query(func.sum(LedgerEntry.amount)).filter(
        LedgerEntry.account_id == account_id,
        LedgerEntry.entry_type == "credit",
        LedgerEntry.event_type == "payment.refunded",
    ).scalar() or Decimal(0)

    # Total fees paid
    fee_account_id = settings.fee_account_id
    total_fees = db.query(func.sum(LedgerEntry.amount)).filter(
        LedgerEntry.account_id == fee_account_id,
        LedgerEntry.merchant_id == merchant_id,
        LedgerEntry.entry_type == "debit",
        LedgerEntry.event_type == "fee.collected",
    ).scalar() or Decimal(0)

    return BalanceSummary(
        merchant_id=merchant_id,
        currency=currency,
        available_balance=account.available_balance,
        pending_balance=account.pending_balance,
        total_balance=account.balance,
        total_earned=total_earned,
        total_fees_paid=total_fees,
        total_refunded=total_refunded,
    )


def get_platform_summary(db: Session, currency: str = "usd") -> PlatformSummary:
    """Get platform-wide financial summary"""

    # Total payment volume (all captures)
    total_volume = db.query(func.sum(LedgerEntry.amount)).filter(
        LedgerEntry.account_id == settings.fee_account_id,
        LedgerEntry.entry_type == "debit",
        LedgerEntry.event_type == "fee.collected",
    ).scalar() or Decimal(0)

    # Scale up from fees to estimate volume
    # (fee = 2.5% of volume, so volume = fee / 0.025)
    if settings.platform_fee_percent > 0:
        estimated_volume = (
            total_volume / Decimal(str(settings.platform_fee_percent)) * Decimal(100)
        )
    else:
        estimated_volume = Decimal(0)

    # Fee account balance
    fee_account = db.query(Account).filter(
        Account.id == settings.fee_account_id
    ).first()
    total_fees = fee_account.balance if fee_account else Decimal(0)

    # Escrow balance
    escrow_account = db.query(Account).filter(
        Account.id == settings.escrow_account_id
    ).first()
    escrow_balance = escrow_account.balance if escrow_account else Decimal(0)

    # Total refunds
    total_refunds = db.query(func.sum(LedgerEntry.amount)).filter(
        LedgerEntry.event_type == "payment.refunded",
        LedgerEntry.entry_type == "debit",
    ).scalar() or Decimal(0)

    return PlatformSummary(
        currency=currency,
        total_volume=estimated_volume,
        total_fees=total_fees,
        escrow_balance=escrow_balance,
        total_refunds=total_refunds,
        net_revenue=total_fees - total_refunds * Decimal("0.025"),
    )
